      missed_tactic: (p) => `${p.occ} veces, en ${p.games} partidas, tenías una línea forzada que ganaba material y jugaste otra cosa.${p.fork ? ` ${p.fork} eran dobles ataques.` : ""} Te costó ${p.impact} puntos de probabilidad de victoria por partida.`,
      hanging_piece: (p) => `${p.occ} veces, en ${p.games} partidas, tu jugada dejó una pieza sin defensa y el rival se la comió. ${p.impact} puntos de probabilidad de victoria por partida.`,
      missed_capture: (p) => `${p.occ} veces, en ${p.games} partidas, había una pieza sin defensa, o de más valor, para capturar y jugaste otra cosa.`,
      allowed_mate: (p) => `${p.occ} veces, en ${p.games} partidas, tu jugada permitió mate en cinco o menos${p.brm ? `, ${p.brm} de ellas en el pasillo` : ""}.`,
      missed_mate: (p) => `${p.occ} veces tuviste mate en cinco o menos y lo dejaste pasar. Muestra pequeña, pero cada una era un punto entero.`,
